@module generators  src=generators.lua  loc=738  mode=namespace  self=generators

# Invariants & contracts
  @invariant  pure module, no state; a stage is fn(stream, host, params, ctx) -> { notes, delta }  @ 6
  @invariant  stream and host share one shape; stages read stream, host is the untouched original  @ 7
  @invariant  pb/ccs are absolute curves over the closed window (edge values seeded); pb val is cents  @ 9
  @invariant  ctx binds resolution, pbRangeCents, nextSameLaneNote -- no notation among them  @ 10
  @invariant  periods are QN per the periodQN convention -- scalar or {num,den}  @ 11
  @invariant  a derived note's intent is its source's moved by the cents it stands off, else absent  @ 13
  @invariant  mode is the stream fold -- replace overwrites the dest channel, augment adds to it  @ 16
  @contract  chord-stamp stamps a poly pattern on each region member; lane-1 is the pattern's root  @ 180
  @contract  every voice moves by the cents root -> trigger; voice keeps trigger vel/window  @ 181
  @contract  a voice is named from the trigger's step moved by its own interval from the root  @ 182
  @contract  no lane-1 note in the pattern -> inert (empty result)  @ 183
  @contract  portamento glides each abutting pair of the host's monophonic line -> lane-1 pb-delta  @ 230
  @contract  abutment is exact -- the tail must reach the successor's onset, else the pair is silent  @ 231
  @contract  the anchor is the successor's onset; 'in' departs on it, 'away' arrives a tick before it  @ 232
  @contract  an anchor outside the window can only be placed away; a note host's successor always is  @ 233
  @contract  glide spans `over` QN, or that per octave when per='octave'; pb-range clamps the target  @ 234
  @contract  a gap, a unison target, or no successor at all -> that pair contributes nothing  @ 235
  @contract  lfo tiles a normalized curve at 1/period QN, offset + scale map each val, unit-naive  @ 340
  @contract  a named wave is the body expanded; 'custom' (or no wave) reads the stored one  @ 341
  @contract  breakpoints are a displacement from the dest's rest, which the augment fold lays them on  @ 342
  @contract  each cycle stretches the body lengthPpq -> period ticks; both window edges seeded  @ 343
  @contract  onset QN ramps the whole displacement in from rest, linearly from the window start  @ 344
  @contract  dest is a per-entry param; registry dest is only its seed + note-vs-continuous marker  @ 534

# Shapes
  @shape  stream/host = { window={startppq,endppq}, chan, lane, id, notes={ {pitch,vel,detune,ppq,endppq,[lane],[intentCents]},.. }, pas={ {ppq,pitch,vel},.. }, ccs={ [cc]={ {ppq,val,shape,[tension]},.. } }, ats={ {ppq,val},.. }, pb={ {ppq,val,shape,[tension]},.. } }  @ 8
  @shape  result = { notes = { {ppq,endppq,pitch,vel,detune,[intentCents]}, ... }, delta = { {ppq,val,shape,[tension]}, ... } }  @ 12
  @shape  kinds[kind] = { expand, mode='replace'|'augment', dest='note'|'pb'|<cc>, dests?='any'|'pb'|'cc', label, glyph, defaults, fields }  @ 14
  @shape  field = { field, label, widget, base?, coarse?, min?, max?, options?, when?, kind?, poly?, quantity?='magnitude', signed?, frac? }  @ 15
  @shape  fxPatterns (ds project) = { [name] = { kind='notes'|'curve', lengthPpq, rpb=rowsPerBeat, root?=midiPitch, specs?={ {lane,ppq,endppq,pitch,vel,detune,delay,sample?},.. }, points?={ {ppq,val,shape,tension?},.. } } }  @ 19
  @shape  destProfile = { unit, rest, bipolar, magScale } -- continuous dests only ('pb' | cc number)  @ 535
  @shape  parkWindows -> { {evType='note'|'cc'|'pb', chan, cc?, id, startppq, endppq}, ... } (cc on cc windows only)  @ 661

