# Private functions
  @fn periodTicks(period, resolution)  @ 28-31
  -- Note arithmetic
  @fn interval(a, b)  @ 37-39
      -- Cents between two notes' realised pitches. The microtonal offset already rides
      -- in detune, so this is pure note arithmetic -- no temper needed.
  @fn displaced(note, cents)  @ 43-45
      -- The inverse: a note displaced by cents, placed back on (pitch, detune). A pitch demand is
      -- cents here and never notation steps. see docs/generators.md § The ctx discipline
  @fn inherited(src, cents)  @ 49-51
      -- The name that rides with it: the source's intent moved by the cents this note stands off it.
      -- A source carrying none derives none, and the note reads as it sounds; see docs/tuning.md § The written step
  @fn retrig(stream, host, params, ctx)  @ 55-75
      @contract  retrig tiles the host window with evenly-spaced same-pitch fxNotes; every hit is derived  @ 53
      @contract  velocity ramps params.ramp per tile from the host vel, clamped 1..127; detune inherited verbatim  @ 54
  @fn trill(stream, host, params, ctx)  @ 78-103
      @contract  trill alternates host pitch with a note `cents` off what it sounds; every hit derived  @ 77
  @fn playingAt(events, t)  @ 106-115
      -- Notes sounding at logical tick `t`, ascending by realised pitch (semitone*100 + detune cents).
  @fn arpIndex(count, dir, i)  @ 119-127
      -- Which voice of the active set step `i` plays, by direction. updown bounces without
      -- repeating the extremes (span 2*(n-1)); up/down wrap.
  @fn arp(stream, host, params, ctx)  @ 132-153
      @contract  arp samples the sounding notes at each step (period QN), playing one by `dir`  @ 129
      @contract  dir up|down|updown cycles the current active set; an empty active set -> a rest  @ 130
      @contract  hits abut (endppq = next step), clamped to the window; vel/detune from the voice  @ 131
  @fn ostinato(stream, host, params, ctx)  @ 157-178
      @contract  ostinato gates the sounding region notes by a stored pattern -- pattern gives onset/dur/vel, each voice its pitch/detune  @ 155
      @contract  every voice sounding at a gate onset emits (none -> rest); the pattern loops from the window start; no lengthPpq -> inert  @ 156
  @fn chordStamp(stream, host, params, ctx)  @ 186-207
      -- Voices carry their authored detune (intent); on one channel only lane 1's detune realises via pb, so a
      -- microtonal chord sounds faithfully only in 12-ET -- the hand-authored-chord limit. see docs/tuning.md
  @fn glideSequence(stream, host, ctx)  @ 210-220
      -- The monophonic sequence a host presents, in ppq order. see docs/generators.md § Portamento ¶5-6
  @fn glideTicks(params, target, resolution)  @ 224-228
      -- How long a glide runs: `over` QN outright, or that much per octave of the interval it crosses --
      -- one stored fraction read as a duration or as a rate.
  @fn slide(stream, host, params, ctx)  @ 236-283
  -- LFO waves
  @fn curveAt(points, a)  @ 328-338
      -- Linear-interpolated normalized value at authored ppq `a`; points ascend in ppq, edges clamp flat.
  @fn lfo(stream, host, params, ctx)  @ 345-386
  @fn velPattern(stream, host, params, ctx)  @ 390-407
      @contract  velPattern rewrites stream-note velocities by a pattern; other fields carry verbatim  @ 388
      @contract  pattern steps per distinct onset (a chord shares one step) and cycles; vel clamps 1..127  @ 389
  -- Generator registry
  -- Dest: a per-entry target, and what each target's numbers mean
  -- Region park predicate + windows
  -- Curve thinning (freeze to group)
  @fn ridesLinear(p)  @ 690
      -- A shape governs the segment to its *right*, so a point is safe to lose only if it and its
      -- predecessor both ride linearly; a missing shape counts as non-linear.

